parameters.jsCode:
const root = $json.body ?? $json;
const data = root.data ?? root;
const key = data.key ?? {};

const jid =
  key.remoteJid ??
  data.remoteJid ??
  root.remoteJid ??
  '';

const phone = String(jid)
  .replace('@s.whatsapp.net', '')
  .replace('@c.us', '')
  .replace(/\D/g, '');

const name =
  data.pushName ??
  root.pushName ??
  data.notifyName ??
  'Aluno';

const msg = data.message ?? root.message ?? {};

const text =
  msg.conversation ??
  msg.extendedTextMessage?.text ??
  msg.imageMessage?.caption ??
  msg.videoMessage?.caption ??
  data.text ??
  root.text ??
  '';

let messageType =
  data.messageType ??
  root.messageType ??
  '';

if (!messageType) {
  if (msg.audioMessage) messageType = 'audio';
  else if (msg.imageMessage) messageType = 'image';
  else if (msg.videoMessage) messageType = 'video';
  else messageType = 'text';
}

const fromMe = Boolean(key.fromMe ?? data.fromMe ?? false);
const isGroup = String(jid).includes('@g.us');

return [{
  json: {
    phone,
    jid,
    name,
    message: String(text ?? '').trim(),
    message_type: messageType,
    from_me: fromMe,
    is_group: isGroup,
    event: root.event ?? '',
    received_at: new Date().toISOString()
  }
}];

const j = $json;

const student = j.found
  ? j.student
  : {
      name: j.name,
      phone: j.phone,
      overall_level: 'A1',
      goal: 'Aprender inglês',
      correction_mode: 'balanced'
    };

const weaknesses = Array.isArray(j.weaknesses) ? j.weaknesses : [];
const vocab = Array.isArray(j.vocabulary_review) ? j.vocabulary_review : [];
const history = Array.isArray(j.recent_messages) ? j.recent_messages : [];

const teacherPrompt = `
Você é Emma, professora particular de inglês do RS English.

ALUNO
Nome: ${student.name || j.name || 'Aluno'}
Nível atual: ${student.overall_level || 'A1'}
Objetivo: ${student.goal || 'Aprender inglês'}
Modo de correção: ${student.correction_mode || 'balanced'}

REGRAS
- Converse principalmente em inglês.
- Para A1/A2, use português apenas quando uma explicação realmente ajudar.
- Mantenha a conversa natural.
- Não transforme cada mensagem em uma aula longa.
- Corrija erros relevantes.
- No modo balanced, priorize no máximo 1 ou 2 correções por resposta.
- Depois da correção, continue a conversa com uma pergunta curta.
- Incentive o aluno a responder em inglês.
- Não invente progresso, notas ou fatos sobre o aluno.
- Não diga que um nível CEFR foi oficialmente alterado.

ERROS/FRAGILIDADES RECENTES
${JSON.stringify(weaknesses)}

VOCABULÁRIO PARA REVISÃO
${JSON.stringify(vocab)}

HISTÓRICO RECENTE
${JSON.stringify(history)}

MENSAGEM ATUAL DO ALUNO
${j.message}

Responda apenas com a mensagem que deverá ser enviada ao aluno no WhatsApp.
`.trim();

const evaluatorPrompt = `
Você é o avaliador pedagógico invisível do RS English.
Analise apenas a produção do aluno. Não converse com ele.

Aluno:
${j.message}

Nível conhecido:
${student.overall_level || 'A1'}

Retorne SOMENTE JSON válido, sem markdown, neste formato:
{
  "grammar_score": 0,
  "vocabulary_score": 0,
  "fluency_score": 0,
  "comprehension_score": 0,
  "detected_level": "A1",
  "errors": [
    {
      "category": "grammar",
      "topic": "past_simple",
      "original": "texto incorreto",
      "corrected": "texto corrigido",
      "explanation": "explicação curta",
      "severity": "low|medium|high"
    }
  ],
  "skills": [
    {
      "code": "past_simple",
      "score": 0,
      "success": false
    }
  ]
}

Regras:
- scores entre 0 e 100.
- errors pode ser [].
- skills deve usar, quando possível: grammar, vocabulary, speaking, listening, reading, writing, fluency, pronunciation, past_simple, present_simple, present_continuous, articles, prepositions, word_order, irregular_verbs.
- Não promova oficialmente o nível.
`.trim();

return [{
  json: {
    ...j,
    student,
    teacher_prompt: teacherPrompt,
    evaluator_prompt: evaluatorPrompt
  }
}];

const r = $json;

let text = r.output_text;

if (!text && Array.isArray(r.output)) {
  const parts = [];
  for (const item of r.output) {
    if (!Array.isArray(item.content)) continue;
    for (const c of item.content) {
      if (typeof c.text === 'string') parts.push(c.text);
    }
  }
  text = parts.join('\n').trim();
}

if (!text && r.choices?.[0]?.message?.content) {
  text = r.choices[0].message.content;
}

return [{ json: { teacher_message: String(text ?? '').trim() } }];

const r = $json;

let text = r.output_text;

if (!text && Array.isArray(r.output)) {
  const parts = [];
  for (const item of r.output) {
    if (!Array.isArray(item.content)) continue;
    for (const c of item.content) {
      if (typeof c.text === 'string') parts.push(c.text);
    }
  }
  text = parts.join('\n').trim();
}

if (!text && r.choices?.[0]?.message?.content) {
  text = r.choices[0].message.content;
}

text = String(text ?? '')
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

let evaluation;

try {
  evaluation = JSON.parse(text);
} catch (e) {
  evaluation = {
    grammar_score: null,
    vocabulary_score: null,
    fluency_score: null,
    comprehension_score: null,
    errors: [],
    skills: [],
    parse_error: true,
    raw: text
  };
}

return [{ json: { evaluation } }];

